import { defineConfig } from 'vite';
import { readdirSync } from 'node:fs';
import { resolve } from 'node:path';

// Multi-page build: the simulator (index.html) plus the static history pages (history/**/index.html,
// generated by `npm run gen-history`).
function historyPages(): string[] {
  try {
    return (readdirSync('history', { recursive: true }) as string[]).filter((f) => f.endsWith('index.html')).map((f) => resolve('history', f));
  } catch {
    return []; // pages not generated yet
  }
}

export default defineConfig({
  worker: { format: 'es' },
  build: { target: 'es2022', rollupOptions: { input: [resolve('index.html'), ...historyPages()] } },
  test: { include: ['tests/**/*.test.ts'] },
} as Parameters<typeof defineConfig>[0]);
